def solve(path):
    # Simplify an absolute Unix path.
    # Remove surrounding whitespace
    if not isinstance(path, str):
        return ''
    path = path.strip()
    # Ensure it starts with '/'
    if not path.startswith('/'):
        # Not an absolute path per spec; return empty or treat as root
        return ''
    parts = []
    for token in path.split('/'):
        if token == '' or token == '.':
            continue
        if token == '..':
            if parts:
                parts.pop()
            # if at root, stay
        else:
            parts.append(token)
    return '/' + '/'.join(parts)

