def solve(weights, values, capacity):
    """0/1 knapsack: return the largest total value of items (each used at
    most once) whose total weight fits within capacity."""
    cap = capacity if capacity and capacity > 0 else 0
    # Zero-weight items with positive value always fit: take them all.
    base = sum(v for w, v in zip(weights, values) if w <= 0 and v > 0)
    dp = [0] * (cap + 1)
    for w, v in zip(weights, values):
        if w <= 0:
            continue
        for c in range(cap, w - 1, -1):
