def solve(matrix):
    """Return determinant of a square integer matrix.
    Empty matrix (0x0) has determinant 1 by definition.
    Uses recursive expansion by minors (Laplace) for simplicity; works for small matrices.
    """
    # Helper: compute determinant recursively
    def det(mat):
        n = len(mat)
        if n == 0:
            return 1
        if n == 1:
            return mat[0][0]
        if n == 2:
            return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
        # expand along first row
        total = 0
        for col in range(n):
            # build minor matrix
            minor = [row[:col] + row[col+1:] for row in mat[1:]]
            cofactor = ((-1) ** col) * mat[0][col]
            total += cofactor * det(minor)
        return total
    # Validate square
    if not matrix:
        return 1
    size = len(matrix)
    for row in matrix:
        if len(row) != size:
            raise ValueError('Matrix must be square')
    return det(matrix)

