def solve(n, b):
    """Write integer n in base b (2-36), digits 0-9 then a-z, with a
    leading minus sign for negative n."""
    if b < 2 or b > 36:
        raise ValueError('base out of range')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    out = []
    while n:
        out.append(digits[n % b])
        n //= b
    if neg:
        out.append('-')
    return ''.join(reversed(out))

