def solve(matrix):
    """Return integer determinant of a square matrix (list of lists).
    Empty matrix returns 1. Uses Bareiss fraction-free algorithm for exact integers.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a deep copy to avoid mutating input
    a = [list(map(int, row)) for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Pivot zero? find non-zero row to swap
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            # swap rows k and swap_row
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]

